
import { useState, useEffect, useRef } from "react";

// ── 브랜드 컬러 (스플래시/홈 화면 기준) ──────────────────────────
const C = {
  primary:      "#7B61D4",   // 딥 퍼플 (컬러칩 우측)
  primaryLight: "#C07AE0",   // 핑크-퍼플 (컬러칩 좌측)
  primarySoft:  "#EAD9F9",
  primaryBg:    "#F6F0FF",
  splashFrom:   "#C97BE8",   // 스플래시 그라디언트 상단
  splashTo:     "#7B61D4",   // 스플래시 그라디언트 하단
  dark:         "#1E1340",
  mid:          "#5B4D80",
  light:        "#9E8BB5",
  white:        "#FFFFFF",
  surface:      "#FDFAFF",
  border:       "#E8D9F7",
  orange:       "#E8943A",
  orangeBg:     "#FFF4E8",
  green:        "#4CAF88",
  bgOuter:      "#E8D9F7",
};

const LOGO_B64 = "data:image/png;base64,";

// ── 로고 마크 (실제 이미지) ────────────────────────────────────────
